const assert = require('assert');

class Subscription {
    static VALID_TRANSITIONS = {
        pending: ['active'],
        active: ['paused', 'cancelled'],
        paused: ['active', 'cancelled'],
        cancelled: []
    };

    constructor(userId, plan) {
        this.userId = userId;
        this.plan = plan;
        this.state = 'pending';
        this.auditLog = [];
        this.activatedAt = null;
        this.pausedAt = null;
        this.totalPausedMs = 0;
    }

    _transition(newState, ts) {
        const allowed = Subscription.VALID_TRANSITIONS[this.state];
        if (!allowed || !allowed.includes(newState)) {
            throw new Error(`Cannot transition from ${this.state} to ${newState}`);
        }
        const old = this.state;
        this.state = newState;
        this.auditLog.push({ from: old, to: newState, ts });
    }

