pick(pickId, sku, requestedQty, currentDate) {
    if (this.picks[pickId]) {
        return this.picks[pickId];
    }

    const eligibleBatches = this.batches.filter(b => 
        b.sku === sku && b.qty > 0 && b.expiry > currentDate
    );

    eligibleBatches.sort((a, b) => a.expiry.localeCompare(b.expiry));

    const totalAvailable = eligibleBatches.reduce((sum, b) => sum + b.qty, 0);

    const items = [];
    let remaining = requestedQty;
    const originalQtys = {};

    for (const batch of eligibleBatches) {
        originalQtys[batch.batchId] = batch.qty;
    }

    for (const batch of eligibleBatches) {
        if (remaining <= 0) break;
        const take = Math.min(batch.qty, remaining);
        batch.qty -= take;
        remaining -= take;
        items.push({ batchId: batch.batchId, qty: take });
    }

    if (remaining > 0) {
        for (const batch of eligibleBatches) {
            batch.qty = originalQtys[batch.batchId];
        }
        const result = { success: false, reason: 'insufficient_stock', available: totalAvailable };
        this.picks[pickId] = result;
        return result;
    }

    const result = { success: true, items };
    this.picks[pickId] = { items, sku, totalQty: requestedQty };
    return result;
}

