updateScore(factor, weight, ts) {
    const delta = Math.round(factor * weight);
    const newScore = this._clamp(this.score + delta);
    const oldTier = this.tier;
    const newTier = this._getTier(newScore);
    this.score = newScore;
    let tierChanged = false;
    if (newTier !== oldTier) {
        if (ts - this.lastTransitionTs >= this.cooldownPeriod) {
            this.tier = newTier;
            this.lastTransitionTs = ts;
            tierChanged = true;
        }
        // If cooldown hasn't elapsed, score updates but tier stays
    }
    this.audit.push({
        factor, weight, delta, oldScore: newScore - delta, newScore,
        oldTier, currentTier: this.tier, tierChanged, ts
    });
    return { score: this.score, tier: this.tier, tierChanged };
