class MembershipSystem {
    constructor() {
        this.tiers = [
            { name: 'bronze', minPoints: 0, benefits: ['basic_support'] },
            { name: 'silver', minPoints: 100, benefits: ['basic_support', 'priority_queue'] },
            { name: 'gold', minPoints: 300, benefits: ['basic_support', 'priority_queue', 'free_shipping'] },
            { name: 'platinum', minPoints: 600, benefits: ['basic_support', 'priority_queue', 'free_shipping', 'personal_advisor'] }
        ];
        this.members = {};
    }

    addMember(id) {
        this.members[id] = { id, points: 0, tier: 'bronze', benefits: ['basic_support'],
            graceMonthsLeft: 0, history: [] };
    }

    _tierIndex(name) { return this.tiers.findIndex(t => t.name === name); }

    _tierForPoints(pts) {
        let best = this.tiers[0];
        for (const t of this.tiers) if (pts >= t.minPoints) best = t;
        return best;
    }

    // Process monthly update. Add pointsEarned, then:
    // PROMOTE (qualified > current): snapshot benefits, graceMonthsLeft=2,
    //   log {action:'promote', from, to, points, month}.
    // DEMOTE (qualified < current): if grace > 0, decrement, log 'grace'.
    //   If grace === 0, demote, snapshot benefits, log 'demote'.
    // STAY: log {action:'stay', tier, month}.

golden_completion:
processMonth(memberId, pointsEarned, month) {
    const m = this.members[memberId];
    m.points += pointsEarned;
    const q = this._tierForPoints(m.points);
    const qIdx = this._tierIndex(q.name), cIdx = this._tierIndex(m.tier);
    if (qIdx > cIdx) {
        const from = m.tier;
        m.tier = q.name; m.benefits = [...q.benefits]; m.graceMonthsLeft = 2;
        m.history.push({ action: 'promote', from, to: m.tier, points: m.points, month });
    } else if (qIdx < cIdx) {
        if (m.graceMonthsLeft > 0) {
            m.graceMonthsLeft--;
            m.history.push({ action: 'grace', tier: m.tier, graceMonthsLeft: m.graceMonthsLeft, month });
        } else {
            const from = m.tier;
            m.tier = q.name; m.benefits = [...q.benefits];
            m.history.push({ action: 'demote', from, to: m.tier, points: m.points, month });
        }
    } else { m.history.push({ action: 'stay', tier: m.tier, month }); }
    return { ...m, benefits: [...m.benefits] };
}

