    if (amount <= 0) return { applied: 0, credit: 0 };
    let rem = amount;
    const allocs = [];
    for (const li of this.lineItems) {
        const owed = li.amount - li.paid;
        if (owed <= 0) continue;
        const a = Math.min(rem, owed);
        li.paid += a; rem -= a;
        allocs.push({ desc: li.desc, applied: a });
        if (rem <= 0) break;
    }
    const applied = amount - rem;
    this.credit += rem;
    this.payments.push({ reference, amount, applied, creditAdded: rem, allocations: allocs });
    this.status = this.totalPaid >= this.totalDue ? 'paid' : this.totalPaid > 0 ? 'partial' : this.status;
    return { applied, credit: rem };
}

