processReturn(orderId, items, orderDay, returnDay) {
    const elapsed = returnDay - orderDay;
    if (elapsed < 0) return null;
    if (elapsed > this.creditOnlyDays) {
        this.returns.push({ orderId, status: 'rejected', reason: 'past_return_window', elapsed });
        return { status: 'rejected', refund: 0, credit: 0 };
    }
    const sub = items.reduce((s, i) => s + i.price * i.qty, 0);
    const fee = elapsed <= this.fullRefundDays ? 0 : parseFloat((sub * this.restockingPct).toFixed(2));
    const net = parseFloat((sub - fee).toFixed(2));
    const method = elapsed <= this.fullRefundDays ? 'refund' : 'credit';
    const result = { status: 'approved', method, subtotal: sub, restocking: fee,
        refund: method === 'refund' ? net : 0, credit: method === 'credit' ? net : 0 };
    this.returns.push({ orderId, ...result, elapsed });
    return result;
}

