    static DRUGS = {
        'oxycodone':  { controlled: true,  maxDaily: 60,  minRefillMs: 72*3600000, copay: { generic: 10, brand: 35 } },
        'ibuprofen':  { controlled: false, maxDaily: 999, minRefillMs: 0,          copay: { generic: 5,  brand: 15 } },
